// O fluxo de anúncio responde {ok, link: '.../anuncio-video-ver?job=...'}: guarda o job no imóvel.
const c = $('🐘 imv_api').first().json.r.contexto;
const r = $input.first().json || {};
const m = String(r.link || '').match(/job=([a-z0-9-]+)/);
if (!r.ok || !m) return [{ json: { ok: false, erro: (r.erros && r.erros.join(' ')) || r.erro || 'Não consegui pedir o vídeo agora. Tente de novo.', id: c.id, salvar: JSON.stringify({ status: 'erro', erro: 'falha ao pedir' }) } }];
return [{ json: { ok: true, job: m[1], id: c.id, salvar: JSON.stringify({ status: 'gerando', job: m[1] }) } }];

const c = $('🐘 imv_api').first().json.r.contexto;
const g = $input.first().json || {};
if (!g.video) return [{ json: { ok: false, id: c.id, salvar: JSON.stringify({ status: 'erro', job: c.job, erro: 'vídeo não encontrado na oficina' }) } }];
return [{ json: { ok: true, id: c.id, salvar: JSON.stringify({ status: 'pronto', job: c.job, url: g.video || g.video_musica, musica: g.video_musica || null, capa: g.capa || null, pagina: c.pagina || null }) } }];

// Junta cada imóvel pendente com o andamento do vídeo dele.
const pend = $('🐘 Vídeos pendentes').all().map(i => i.json);
return $input.all().map((it, k) => ({ json: { ...pend[k], s: it.json || {} } }))
  .filter(x => x.s.etapa === 'pronto' || x.s.etapa === 'erro')
  .map(x => ({ json: { id: x.id, job: x.job, pasta: x.pasta, pagina: x.s.pagina || x.pagina || '', erro: x.s.etapa === 'erro' ? String(x.s.erro || 'falhou').slice(0, 200) : '' } }));

return $input.all().map((it, k) => { const x = $('🧩 Terminou?').all()[k].json, g = it.json || {};
  const ok = !x.erro && g.video;
  return { json: { id: x.id, salvar: JSON.stringify(ok ? { status: 'pronto', job: x.job, url: g.video || g.video_musica, musica: g.video_musica || null, capa: g.capa || null, pagina: x.pagina || null } : { status: 'erro', job: x.job, erro: x.erro || 'vídeo não encontrado' }) } }; });
